/**
 * Moves an issue to another project, allocating it the target project's next
 * number (per ADR 0011). The old number is left retired: it stays recorded
 * against the source project forever, since `nextIssueNumber` takes the max
 * over every row the project has ever held, live or not.
 */
export async function moveIssueToProject(
  orgId: OrgId,
  issueId: IssueId,
  toProjectId: ProjectId,
  toNumber: number,
): Promise<Issue> {
  const row = getDb()
    .update(issues)
    .set({
      projectId: toProjectId,
      number: toNumber,
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .returning()
    .get();

  if (!row) throw new Error(`Issue ${issueId} not found`);
  return toIssue(row);
}

/** Cascade behind `ProjectService.archiveProject`; returns the row count. */

