/**
 * Moves an issue to another project of the same workspace (ADR 0011). Needs
 * both `issue:update` on the issue and `issue:create` on the target project —
 * the same gates editing the issue and creating one there would need — and
 * the target project's issue quota applies exactly as it would to a create.
 * The issue is re-numbered under the target project; its old number is
 * retired in the source project. A move within the same project is a no-op
 * that publishes nothing.
 */
export async function moveIssueToProject(
  actor: Actor,
  input: MoveIssueToProjectInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const before = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(before));
  assertNotArchived("Issue", before.id, before);

  if (before.projectId === input.toProjectId) {
    return before;
  }

  const targetProject = requireFound(
    await projectRepo.findProjectById(input.orgId, input.toProjectId),
    "Project",
    input.toProjectId,
  );
  assertNotArchived("Project", targetProject.id, targetProject);
  assertCan(actor, "issue:create", projectResource(targetProject));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
  const used = await issueRepo.countIssues(input.orgId, input.toProjectId);
  if (wouldExceedLimit(org.plan, "issuesPerProject", used)) {
    throw new Error(
      `Plan ${org.plan} allows no more issues in project ${targetProject.key}`,
    );
  }

  const toNumber = await issueRepo.nextIssueNumber(
    input.orgId,
    input.toProjectId,
  );
  const after = await issueRepo.moveIssueToProject(
    input.orgId,
    input.issueId,
    input.toProjectId,
    toNumber,
  );

  await emit("issue.moved", {
    ...actorEnvelope(actor),
    issueId: after.id,
    fromProjectId: before.projectId,
    toProjectId: after.projectId,
    fromNumber: before.number,
    toNumber: after.number,
  });

  return after;
}

